import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { QuizService } from './services/quiz.service';
import { Lecon } from '../shared/models/lecon.model';
import { Question } from '../shared/models/question.model';

@Component({
  selector: 'app-quiz',
  templateUrl: './quiz.component.html',
  styleUrls: ['./quiz.component.css']
})
export class QuizComponent implements OnInit {
  leconId: number = 0;
  lecon: Lecon | null = null;
  questions: Question[] = [];
  currentQuestionIndex = 0;
  userAnswer = '';
  submitted = false;
  submitting = false;
  evaluation = '';
  points = 0;
  loading = true;

  constructor(
    private route: ActivatedRoute,
    private router: Router,
    private quizService: QuizService
  ) {}

  ngOnInit(): void {
    this.leconId = Number(this.route.snapshot.paramMap.get('leconId'));
    if (this.leconId) {
      this.loadQuizData();
    }
  }

  loadQuizData(): void {
    this.quizService.obtenirLeconDetails(this.leconId).subscribe({
      next: (data) => {
        this.lecon = data;
        this.questions = data.questions || [];
        this.loading = false;
      },
      error: () => this.loading = false
    });
  }

  submitAnswer(): void {
    if (!this.userAnswer.trim()) return;
    const currentQ = this.questions[this.currentQuestionIndex];
    this.submitting = true;

    this.quizService.soumettre(currentQ.id, this.userAnswer).subscribe({
      next: (response) => {
        this.evaluation = response.evaluation;
        this.points = response.points;
        this.submitted = true;
        this.submitting = false;
      },
      error: () => this.submitting = false
    });
  }

  nextQuestion(): void {
    if (this.currentQuestionIndex < this.questions.length - 1) {
      this.currentQuestionIndex++;
      this.userAnswer = '';
      this.submitted = false;
      this.evaluation = '';
    } else {
      this.router.navigate(['/dashboard']);
    }
  }
}
<div class="container animate-fade-in" *ngIf="!loading && questions.length > 0">
  <div class="quiz-card glass-panel">
    <div class="quiz-header">
      <div>
        <span class="badge badge-gold">Leçon : {{ lecon?.titre }}</span>
        <h2>التقييم والتمرين التفاعلي</h2>
      </div>
      <div class="question-counter">
        السؤال {{ currentQuestionIndex + 1 }} من {{ questions.length }}
      </div>
    </div>

    <div class="question-box">
      <h3 class="question-text">{{ questions[currentQuestionIndex].texte }}</h3>

      <div class="answer-section" *ngIf="!submitted">
        <label>أدخل إجابتك المكتوبة:</label>
        <textarea 
          [(ngModel)]="userAnswer" 
          class="form-textarea" 
          rows="4" 
          placeholder="اكتب إجابتك هنا بدقّة..."
        ></textarea>

        <button (click)="submitAnswer()" class="btn-primary" [disabled]="submitting || !userAnswer.trim()">
          <i class="fa-solid fa-paper-plane" *ngIf="!submitting"></i>
          <span>{{ submitting ? 'جارٍ التقييم بالذكاء الاصطناعي...' : 'إرسال إجابتي' }}</span>
        </button>
      </div>
    </div>

    <!-- Evaluation Feedback Box -->
    <div *ngIf="submitted" class="evaluation-box glass-card animate-fade-in">
      <div class="eval-header">
        <div class="points-badge">
          <i class="fa-solid fa-trophy gold-text"></i> +{{ points }} نقاط مكتسبة !
        </div>
        <h4>تقييم فوري بالذكاء الاصطناعي</h4>
      </div>
      <p class="eval-body">{{ evaluation }}</p>

      <div class="eval-actions">
        <button *ngIf="currentQuestionIndex < questions.length - 1" (click)="nextQuestion()" class="btn-primary">
          السؤال التالي <i class="fa-solid fa-arrow-left"></i>
        </button>
        <button *ngIf="currentQuestionIndex === questions.length - 1" (click)="nextQuestion()" class="btn-primary">
          إنهاء الاختبار والعودة إلى لوحة التحكم <i class="fa-solid fa-check-double"></i>
        </button>
      </div>
    </div>
  </div>
</div>

<div class="container" *ngIf="!loading && questions.length === 0">
  <div class="glass-card text-center" style="padding: 3rem;">
    <h3>لا توجد أسئلة متاحة في هذا الدرس.</h3>
    <a routerLink="/dashboard" class="btn-primary" style="margin-top: 1rem;">العودة إلى لوحة التحكم</a>
  </div>
</div>
